// === Helper Functions ===

function cleanSpaces(s) {
    return String(s ?? '')
        .replace(/[\u00A0\u1680\u2000-\u200D\u202F\u205F\u3000\uFEFF]/g, ' ')
        .replace(/[\t\r\n]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

function onlyDigits(s) {
    return String(s ?? '').replace(/\D/g, '');
}

function normVatId(v) {
    if (v === null || v === undefined || v === '') return null;
    let s = onlyDigits(v);
    if (!s) return null;
    if (/^0+$/.test(s)) return '0';
    if (s.length < 13) s = s.padStart(13, '0');
    return s;
}

function normBranch(b) {
    if (b === null || b === undefined) return null;
    let raw = String(b).trim();
    if (!raw || raw === 'รวม') return '00000';
    let s = onlyDigits(raw);
    if (!s) return '00000';
    if (s === '0') s = '0';
    return s.padStart(5, '0');
}

function parseAmount(val) {
    if (val === null || val === undefined || val === '') return null;
    if (typeof val === 'number' && Number.isFinite(val)) return val;
    const normalized = String(val).replace(/[^\d.\-]/g, '');
    if (!normalized) return null;
    const n = Number(normalized);
    return Number.isNaN(n) ? null : n;
}

function normalizeCompanyName(name) {
    if (!name) return null;
    let s = cleanSpaces(String(name));
    s = s.replace(/[“”"']/g, '');
    s = cleanSpaces(s);
    return s || null;
}

// === MAIN LOGIC ===

// 1. ตั้งตัวแปรเก็บค่า
let reportCompany = null;
let reportTaxFormId = null;
const out = [];

// 2. Loop ครั้งแรก: เพื่อหา Header รายงาน (โดยดูจากทุกบรรทัด)
for (const item of items) {
    // รองรับทั้งแบบมี .json และไม่มี
    const r = item.json ? item.json : item; 

    const reportTitle = cleanSpaces(r['ชื่อรายงาน : '] ?? '');
    const reportValue = cleanSpaces(r['รายงานภาษีซื้อ'] ?? '');

    // เช็คหาชื่อบริษัทรายงาน (ไม่สนใจว่าบรรทัดนั้นจะเป็น invoice หรือไม่)
    if (reportTitle.includes('ชื่อกิจการ') && reportValue) {
        reportCompany = reportValue;
    }
    // เช็คหาเลขที่แบบภาษี
    if (reportTitle.includes('เลขที่แบบภาษี') && reportValue) {
        reportTaxFormId = reportValue;
    }
}

// 3. Loop ครั้งที่สอง: เพื่อจัดการข้อมูล Invoice และใส่ค่าที่หาได้ลงไป
for (const item of items) {
    // รองรับทั้งแบบมี .json และไม่มี
    const r = item.json ? item.json : item; 

    const inv = cleanSpaces(r['เลขที่ใบกำกับภาษี'] ?? '');
    const branchText = cleanSpaces(r['สาขา/สำนักงานใหญ่'] ?? '');

    // กรอง: ต้องมีเลขที่ใบกำกับ และ ไม่ใช่บรรทัด 'รวม'
    if (!inv || branchText === 'รวม') {
        continue;
    }

    // ---- Mapping Data ----
    const date = cleanSpaces(r['วันที่ใบกำกับภาษี'] ?? '');
    const ref_doc = cleanSpaces(r['เลขที่เอกสารอ้างอิง'] ?? '');
    const doc_title = cleanSpaces(r['ประเภทใบกำกับ'] ?? '');
    const contact_code = cleanSpaces(r['รหัสผู้ติดต่อ'] ?? '');
    const vname = cleanSpaces(r['ผู้ติดต่อ'] ?? '');
    const vvat = r['เลขทะเบียนผู้เสียภาษี'] ?? '';
    const vbr = r['สาขา/สำนักงานใหญ่'] ?? '';
    const net = r['รายการภาษี 7%'];
    const vat = r['ภาษีมูลค่าเพิ่ม'];
    const grand = r['มูลค่ารวมภาษี'];
    const status = cleanSpaces(r['สถานะ'] ?? '');

    const vendor_name = normalizeCompanyName(vname);
    const vendor_vat_id = normVatId(vvat);
    const vendor_branch = normBranch(vbr);
    const net_amount = parseAmount(net);
    const vat_amount = parseAmount(vat);
    const grand_total = parseAmount(grand);

    out.push({
        json: {
            invoice_number: inv,
            date_raw: date,
            vendor_name,
            vendor_vat_id,
            vendor_branch,
            net_amount,
            vat_amount,
            grand_total,
            ref_doc,
            doc_title: doc_title || null,
            contact_code,
            status_text: status || null,

            // ใส่ค่าที่ดึงได้จาก Loop แรก
            report_company_name: reportCompany,
            report_tax_form_id: reportTaxFormId
        },
        pairedItem: item.pairedItem
    });
}

return out;

