/**
 * เทียบตัวเลขเงิน 
 */
function sameAmount(a, b, eps = 0.01) {
    if (a == null || b == null) return false;
    const na = Number(a);
    const nb = Number(b);
    if (Number.isNaN(na) || Number.isNaN(nb)) return false;
    return Math.abs(na - nb) <= eps;
}

/**
 * ลบช่องว่างหัว-ท้าย
 */
function cleanSpaces(s) {
    return String(s ?? '').trim(); 
}

/**
 * ปรับชื่อให้เป็นมาตรฐานเดียวกัน
 */
function normalizeNameForCompare(s) {
    if (!s) return "";
    let name = String(s);
    const patterns = [
        /\(มหาชน\)/g, /มหาชน/g, /\(จำกัด\)/g, /จำกัด/g, /จํากัด/g, 
        /บมจ\./g, /บจก\./g, /บริษัท/g, /\s+/g
    ];
    patterns.forEach(pattern => {
        name = name.replace(pattern, '');
    });
    return name;
}

// --- 1) Get Data ---
const excelItems = $items('Code: Normalize rows', 0, 0);
const excelRows  = excelItems.map(i => i.json);

const dbItems = $items('Normalize DB Rows', 0, 0);
const dbRows  = dbItems.map(i => i.json);

// --- 2) Build Map (DB) เพื่อใช้ค้นหา ---
const dbMap = new Map();
for (const row of dbRows) {
    const key = [row._norm_invoice_number, row._norm_vendor_vat_id, row._norm_vendor_branch].join('|');
    if (!dbMap.has(key)) {
        dbMap.set(key, row);
    }
}

// --- 3) Match Excel with DB (ส่งกลับเฉพาะรายการที่มีคู่เท่านั้น) ---
const out = [];

for (let index = 0; index < excelRows.length; index++) {
    const r = excelRows[index];
    const invoice_number = r.invoice_number; 
    const vendor_vat_id  = r.vendor_vat_id;
    const vendor_branch  = r.vendor_branch;
    const vendor_name    = r.vendor_name;

    const key = [invoice_number, vendor_vat_id, vendor_branch].join('|');
    const inv = dbMap.get(key);

    // --- เงื่อนไขสำคัญ: ถ้าไม่มีใน PDF (DB) ให้ข้ามแถวนี้ไปเลย ---
    if (!inv) continue;

    // --- ส่วนการเปรียบเทียบข้อมูล (เพราะมีคู่อยู่แล้ว) ---
    const invoice_number_status = (invoice_number === inv._norm_invoice_number);
    const date_raw_status = (cleanSpaces(r.date_raw) === cleanSpaces(inv.date_raw));
    const vendor_name_status = (normalizeNameForCompare(vendor_name) === normalizeNameForCompare(inv._norm_vendor_name));
    const vendor_vat_id_status  = (vendor_vat_id  === inv._norm_vendor_vat_id);
    const vendor_branch_status  = (vendor_branch  === inv._norm_vendor_branch);
    const net_amount_status  = sameAmount(r.net_amount,  inv.net_amount);
    const vat_amount_status  = sameAmount(r.vat_amount,  inv.vat_amount);
    const grand_total_status = sameAmount(r.grand_total, inv.grand_total);

    const all_ok = [
        invoice_number_status, date_raw_status, vendor_name_status,
        vendor_vat_id_status, vendor_branch_status,
        net_amount_status, vat_amount_status, grand_total_status
    ].every(v => v === true);

    out.push({
        json: {
            source: 'match_found',
            invoice_id: inv.id,
            invoice_number, 
            vendor_vat_id, 
            vendor_branch, 
            vendor_name,
            comparison: {
                invoice_number_status, 
                date_raw_status, 
                vendor_name_status,
                vendor_vat_id_status, 
                vendor_branch_status,
                net_amount_status, 
                vat_amount_status, 
                grand_total_status,
            },
            all_ok,
        },
        pairedItem: excelItems[index]?.pairedItem,
    });
}

// --- Pass 2 เดิมที่หาตัว missing_in_excel ถูกตัดออกไปแล้วเพื่อให้ return เฉพาะตัวที่มีคู่ ---

return out;

const items = $input.all();
if (!items.length) return [];

// -------------------------------------
// thaiToLatin: แปลงไทย → ตัวละติน
// -------------------------------------
function thaiToLatin(input) {
  if (!input) return '';

  const THAI_DIGITS = '๐๑๒๓๔๕๖๗๘๙';

  const charMap = {
    'ก': 'k','ข': 'kh','ฃ': 'kh','ค': 'kh','ฅ': 'kh','ฆ': 'kh',
    'ง': 'ng',
    'จ': 'ch','ฉ': 'ch','ช': 'ch','ซ': 's','ฌ': 'ch',
    'ญ': 'y',
    'ฎ': 'd','ฏ': 't',
    'ฐ': 'th','ฑ': 'th','ฒ': 'th','ถ': 'th','ท': 'th','ธ': 'th',
    'ณ': 'n','ด': 'd','ต': 't','น': 'n',
    'บ': 'b','ป': 'p','ผ': 'ph','ฝ': 'f','พ': 'ph','ฟ': 'f','ภ': 'ph',
    'ม': 'm','ย': 'y','ร': 'r','ล': 'l','ว': 'w',
    'ศ': 's','ษ': 's','ส': 's','ห': 'h','ฮ': 'h',
    'อ': 'o',
    'ะ': 'a','ั': 'a','า': 'a','ำ': 'am',
    'ิ': 'i','ี': 'i',
    'ุ': 'u','ู': 'u',
    'ึ': 'ue','ื': 'ue',
    'เ': 'e','แ': 'ae','โ': 'o','ใ': 'ai','ไ': 'ai',
    '่': '', '้': '', '๊': '', '๋': '',
    '์': '', 'ํ': '', 'ฯ': '', 'ๆ': '',
    'ฺ': '', '฿': '',
  };

  let out = '';

  for (const ch of input.normalize('NFC')) {

    // English / number
    if (/^[a-zA-Z0-9]$/.test(ch)) {
      out += ch;
      continue;
    }

    // Thai digit → western digit
    const idx = THAI_DIGITS.indexOf(ch);
    if (idx !== -1) {
      out += idx;
      continue;
    }

    // Thai character mapping
    if (ch in charMap) {
      out += charMap[ch];
      continue;
    }

    // Whitespace
    if (/\s/.test(ch)) {
      out += ' ';
      continue;
    }

    // others → space
    out += ' ';
  }

  return out.replace(/\s+/g, ' ').trim();
}

// -------------------------------------
// slugPart: ทำ slug จากชื่อโฟลเดอร์
// -------------------------------------
function slugPart(part) {
  const latin = thaiToLatin(part || '');
  return latin
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 8) || 'p';
}

// -------------------------------------
// FNV-1a 32-bit hash
// -------------------------------------
function fnv1a(str) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash >>> 0) * 0x01000193; // 16777619
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

// -------------------------------------
// MAIN: map items
// -------------------------------------
return items.map(item => {
  const rawBody = item.json.body;

  // แปลง body ให้เป็น object ก่อน (รองรับทั้ง string และ object)
  let body;
  if (typeof rawBody === 'string') {
    try {
      body = JSON.parse(rawBody);
    } catch (e) {
      body = {};
    }
  } else {
    body = rawBody || {};
  }

  // ใช้ path จาก body.schema เช่น "/files/VAT/2568-08/count"
  const dirRaw = String(body.schema || '');

  // split path เป็นส่วน ๆ (รองรับ / หรือ \)
  const parts = dirRaw.split(/[\\/]/).filter(Boolean);

  // เอาโฟลเดอร์ท้าย ๆ 2 ตัวมาทำ slug เช่น "2568-08/count"
  const slug = parts.slice(-2).map(slugPart).join('_') || 'schema';

  // ใช้ full path ที่ normalize แล้วทำ hash
  const normalizedPath = parts.map(p => p.normalize('NFC')).join('/');
  const hash8 = fnv1a(normalizedPath).slice(0, 8);

  // final schema (safe for Postgres)
  let schema = `s_${slug}_${hash8}`
    .toLowerCase()
    .replace(/[^a-z0-9_]/g, '_')
    .slice(0, 63);

  return {
    json: {
      ...item.json,
      headers: {
        ...item.json.headers,
        "content-type": "application/json", // เปลี่ยนให้ตรงกับ output ที่ต้องการ
      },
      body: {
        ...body,
        schema, // เขียนทับ schema เดิมด้วยค่า hash ใหม่
      },
    },
    binary: item.binary,
  };
});
